"""Authored compositions exercising material, vector and choreography controls."""
import copy
from .recipes import layer,text,scene,keys
from ..schemas_animation import AnimationComposition

def type_layer(id,value,**kwargs):
    result=text(id,value,**kwargs)
    result['props'].update(weight=650,line_height=.97,tracking=-.002,mode='lines',duration=.9,stagger=.13,clip=True)
    return result

def sculpture(id,kind='torus',**kwargs):
    props={'kind':kind,'material':'ceramic','color':'$accent','segments':64,'rings':24,'rotation_x':32,'rotation_z':-25,'speed':.23,'roughness':.22,'shadow':True}
    props.update(kwargs.pop('props',{}))
    return layer(id,'mesh',props,**kwargs)

def make(identifier, *, title,width,height,fps,seed):
    base={'title':title,'width':width,'height':height,'fps':fps,'seed':seed,'style':'studio','finishing':{'grain':.055,'vignette':.1,'motion_blur':.55,'samples':3},'bpm':100,'sound':{'music':'ambient','gain':.1,'cues':[]}}
    if identifier=='electric-edit':
        base.update(style='punk',palette={'background':'#16131a','ink':'#efe9dc','accent':'#ef3a80','secondary':'#22aebc','muted':'#48414e','paper':'#f3eddd','line':'#706672','glow':'#efc262'},bpm=120,finishing={'grain':.025,'vignette':.08,'motion_blur':.35,'samples':2},sound={'music':'electro','gain':.13,'cues':[{'time':3,'type':'impact','gain':.18},{'time':6,'type':'whoosh','gain':.15},{'time':10,'type':'impact','gain':.18}]})
        panels=[layer('panel-'+str(i),'shape',{'kind':'rect','fill':'$accent' if i%2 else '$secondary'},x=.1+i*.18,y=.5,width=.1,height=1.5,rotation=-20,tracks={'x':keys((0,-.2+i*.18),(3,.25+i*.18),ease='linear')}) for i in range(6)]
        rotor=[{'id':'assembly','kind':'group','rotation':[20,15,-15],'tracks':{'rz':keys((0,-15),(3,80),ease='linear'),'rx':keys((0,20),(3,-25))}},{'id':'parts','kind':'box','parent':'assembly','dimensions':[.13,.62,.08],'color':'$secondary','metalness':.65,'roughness':.28,'repeat':{'count':36,'layout':'radial','radius':1.7,'wave':.12},'tracks':{'spread':keys((0,.1),(1,.5),(3,0),ease='back_out'),'flip':keys((0,0),(1.5,.3),(3,0))}},{'id':'core','kind':'torus','parent':'assembly','dimensions':[.65,.13,1],'color':'$glow','metalness':.6,'roughness':.22}]
        threads=[layer('thread-'+str(i),'path',{'points':[[-.55,-.2+i*.035],[-.2,.25+i*.02],[.1,-.25+i*.02],[.55,.08+i*.03]],'curve':'smooth','color':'$secondary' if i%2 else '$accent','line_width':.003},width=1.1,height=.9,rotation=-12,tracks={'trim_start':keys((0,0),(4,.7)), 'trim_end':keys((0,.2),(1.6,1),(4,1))}) for i in range(12)]
        base['scenes']=[scene('noise',3,[*panels,text('headline','MAKE\nSOME\nNOISE.',x=.48,y=.48,width=.8,height=.8,size=.25,font='condensed',color='$ink',enter='none',rotation=-4,shadow={'color':'#16131a','blur':.012,'x':.008,'y':.01},tracks={'scale':keys((0,.95),(.35,1),ease='back_out')}),text('count','01 / CHANGE THE RHYTHM',y=.94,width=.9,height=.07,size=.023,font='mono',color='$paper')]),scene('bend',3,[text('ghost','BEND',y=.24,width=.94,height=.5,size=.4,font='condensed',color='$muted',enter='none'),layer('world','scene3d',{'nodes':rotor,'camera':{'position':[1,.5,7.5],'target':[0,0,0],'fov':37},'environment_intensity':.35,'ambient':.5,'exposure':.9},width=.72,height=.85,x=.68,y=.55),text('headline','THE\nRULES.',x=.26,y=.65,width=.44,height=.65,size=.22,font='condensed',enter='none',rotation=3)],transition={'type':'cut','duration':.1}),scene('frequency',4,[*threads,text('headline','FIND YOUR\nFREQUENCY.',width=.88,height=.62,size=.19,font='condensed',enter='none',rotation=-3),text('count','03 / KEEP IT MOVING',y=.94,width=.9,height=.07,size=.023,font='mono')],transition={'type':'wipe','duration':.2}),scene('end',2,[text('headline','STAY\nCURIOUS.',width=.82,height=.72,size=.26,font='condensed',color='$background',enter='none',rotation=3),text('signature','GOOD IDEAS MAKE A LITTLE NOISE.',y=.94,width=.88,height=.07,size=.025,font='mono',color='$background')],background='$accent',transition={'type':'cut','duration':.1})]
        for shot in base['scenes']:
            for item in shot['layers']:
                if item['id']=='count':item['props']['size']=.03
    elif identifier=='contour':
        base['palette']={'background':'#e9e6ee','ink':'#302139','accent':'#7768bc','secondary':'#efac8e','muted':'#9e98ae','paper':'#f9f7fc','line':'#cbc4d6','glow':'#fbecdc'}
        base['sound']={'music':'lofi','gain':.1,'cues':[{'time':4,'type':'whoosh','gain':.16},{'time':9,'type':'chime','gain':.12},{'time':14,'type':'whoosh','gain':.18}]}
        base['scenes']=[
          scene('first-form',4,[layer('wash','shape',{'kind':'rect'},x=.8,y=.52,width=.48,height=1.4,rotation=-16,paint={'kind':'linear','colors':['$paper','$background'],'angle':90}),type_layer('name',title,x=.29,y=.4,width=.51,height=.28,size=.17,align='left'),text('statement','A study in soft edges.',x=.28,y=.66,width=.48,height=.15,size=.04,align='left',font='serif',enter='fade',start=.4),sculpture('hero','torus',x=.73,y=.51,width=.6,height=.94,tracks={'rotation_y':keys((0,-32),(4,15)), 'scale':keys((0,.82),(1.2,1),ease='back_out')})],camera={'tracks':{'zoom':keys((0,1),(4,1.035))}}),
          scene('close-fold',5,[type_layer('back-type','FOLD',y=.43,width=.92,height=.62,size=.45,color='$paper',scale_x=.85),sculpture('close','knot',width=.87,height=1.14,y=.44,props={'color':'$secondary','material':'metal','rotation_x':-12,'rotation_z':17,'tube':.38,'speed':.19},tracks={'rotation_y':keys((0,-40),(5,35)), 'x':keys((0,.58),(5,.47))},props_tracks={'roughness':keys((0,.42),(3,.16))}),text('fold-copy','Complexity, held together.',x=.5,y=.945,width=.85,height=.09,size=.034,font='serif',enter='fade',start=.4)],transition={'type':'cut','duration':.1}),
          scene('ensemble',5,[layer('assembly','group',{},width=.94,height=.84,y=.45,tracks={'rotation':keys((0,-5),(5,4))}),*[sculpture('part-'+str(i),'torus',parent='assembly',x=.21+i*.29,y=.53,width=.42,height=.66,props={'color':c,'rotation_x':12+i*26,'rotation_z':-24+i*28,'speed':.16,'tube':.34},tracks={'scale':keys((0,.1),(.8+i*.2,1),ease='back_out'),'y':keys((0,.74),(.9+i*.2,.53),ease='back_out')}) for i,c in enumerate(['$accent','$secondary','$ink'])],type_layer('ensemble-title','Different forms.\nOne language.',y=.86,width=.86,height=.22,size=.063)],transition={'type':'wipe','duration':.4}),
          scene('signature',4,[sculpture('final','knot',x=.5,y=.55,width=.65,height=.9,props={'color':'$accent','material':'ceramic','tube':.32,'rotation_x':38,'rotation_z':15,'speed':.24},tracks={'scale':keys((0,.86),(4,1.03))},color_tracks={'color':[{'time':0,'value':'$accent'},{'time':4,'value':'$secondary'}]},props_tracks={'roughness':keys((0,.65),(3,.18))}),type_layer('last','Built to bend.',y=.16,width=.88,height=.22,size=.115),text('signature',title,y=.92,width=.7,height=.1,size=.04,font='serif')],transition={'type':'crossfade','duration':.5})]
    elif identifier=='small-seasons':
        base.update(style='paper',palette={'background':'#d9e3db','ink':'#314a40','accent':'#b44963','secondary':'#667fb3','muted':'#9eac99','paper':'#f9f3de','line':'#6d8371','glow':'#e7b968'},finishing={'grain':.13,'vignette':.06,'motion_blur':.45,'samples':3},sound={'music':'ambient','gain':.12,'cues':[{'time':5,'type':'chime','gain':.2},{'time':11,'type':'chime','gain':.15}]})
        stem=layer('stem','path',{'points':[[0,.44],[-.08,.19],[.02,-.15],[0,-.36]],'curve':'smooth','color':'$ink','line_width':.009},width=.3,height=.6,y=.6,enter='draw',enter_duration=2.5)
        leaf={'view_box':[-50,-50,100,100],'paths':[{'d':'M-42 35 C-52 -2 -12 -42 43 -35 C49 5 16 47 -42 35Z','fill':'$muted'},{'d':'M-40 34 Q4 -6 41 -33','stroke':'$ink','width':1.6}]}
        petals=[]
        for i in range(7):
            petals.append(layer('petal-'+str(i),'vector',{'view_box':[-60,-110,120,120],'paths':[{'d':'M0 5 C-53 -11 -60 -62 -22 -93 C13 -125 65 -56 27 -12 C18 -3 7 3 0 5Z','fill':'$accent'},{'d':'M0 2 Q-5 -38 -14 -78','stroke':'$paper','width':1.3,'opacity':.4}]},parent='flower',width=.47,height=.53,x=.5,y=.5,anchor_y=.95,rotation=i/7*360,start=.4+i*.12,enter='pop',enter_duration=1.1,shadow={'color':'#746546','blur':.008,'x':.004,'y':.006},tracks={'scale_y':keys((0,.12),(1.3,1),ease='back_out')}))
        flower=[layer('flower','group',{},width=.34,height=.45,x=.5,y=.4,tracks={'rotation':keys((0,-14),(6,7))}),*petals,layer('center','shape',{'kind':'circle','fill':'$glow'},parent='flower',width=.19,height=.145,x=.5,y=.5,start=1.3,enter='pop')]
        garden=[]
        for i,(x,h,c) in enumerate([(.18,.7,'$accent'),(.5,.85,'$secondary'),(.82,.65,'$glow')]):
            prefix='plant-'+str(i)
            garden.append(layer(prefix,'group',{},x=x,y=.88,width=.3,height=h,anchor_y=.866,tracks={'scale_y':keys((0,.06),(1.8+i*.3,1),ease='back_out'),'rotation':keys((0,-8+i*5),(3,0),(6,3-i*3))}))
            garden.append(layer(prefix+'-stem','path',stem['props'],parent=prefix,width=.32,height=.65,y=.58))
            for j,(lx,ly,angle) in enumerate([(.59,.59,-18),(.42,.73,155)]):garden.append(layer(prefix+'-leaf-'+str(j),'vector',leaf,parent=prefix,width=.34,height=.21,x=lx,y=ly,rotation=angle))
            for item in copy.deepcopy(flower):
                original=item['id'];item['id']=prefix+'-'+original
                if item.get('parent'):item['parent']=prefix+'-'+item['parent']
                else:item.update(parent=prefix,width=.78,height=.42,x=.5,y=.35)
                if item['component']=='vector':item['props']['paths'][0]['fill']=c
                garden.append(item)
        base['scenes']=[scene('seed',5,[layer('card','shape',{'kind':'rect','fill':'$paper','corners':.035},width=.87,height=.88,shadow={'color':'#65786b','blur':.035,'x':.01,'y':.025}),type_layer('title',title,y=.15,size=.086,font='serif',width=.78,height=.15),stem,layer('leaf','vector',leaf,width=.18,height=.22,x=.57,y=.57,rotation=-18,start=1.5,enter='pop',enter_duration=.9),layer('bud','shape',{'kind':'blob','fill':'$accent'},width=.035,height=.065,y=.38,start=2.5,enter='pop'),text('seed-line','Give a small thing time.',y=.87,size=.037,font='serif',enter='fade',start=.8)]),scene('bloom',6,[layer('card','shape',{'kind':'rect','fill':'$paper','corners':.035},width=.87,height=.88,shadow={'color':'#65786b','blur':.035,'x':.01,'y':.025}),stem|{'enter':'none'},layer('leaf-a','vector',leaf,width=.17,height=.22,x=.56,y=.6,rotation=-16),layer('leaf-b','vector',leaf,width=.17,height=.22,x=.45,y=.72,rotation=155),*flower,type_layer('bloom-line','Watch it open.',y=.86,size=.055,font='serif',width=.75,height=.14)],transition={'type':'crossfade','duration':.5}),scene('garden',6,[layer('ground','path',{'points':[[-.5,.1],[-.25,-.03],[.1,.07],[.5,-.06]],'curve':'smooth','color':'$ink','line_width':.003},width=1,height=.2,y=.87),*garden,type_layer('ending','A little care\ngoes a long way.',y=.16,size=.065,font='serif',width=.83,height=.22),text('close','Small seasons. New beginnings.',y=.96,size=.028,font='serif')],transition={'type':'wipe','duration':.55})]
    else:
        base.update(style='studio',palette={'background':'#172a30','ink':'#f0ede2','accent':'#efab77','secondary':'#8fb9ac','muted':'#537278','paper':'#243f47','line':'#345d63','glow':'#f7e0b7'},bpm=120,sound={'music':'electro','gain':.14,'cues':[{'time':4,'type':'whoosh','gain':.16},{'time':9,'type':'impact','gain':.15}]})
        curves=[]
        for i in range(18):
            offset=(i-8.5)*.014
            curves.append(layer('thread-'+str(i),'path',{'points':[[-.55,-.08+offset],[-.3,.22+offset],[-.05,-.25+offset],[.25,.15+offset],[.55,-.12+offset]],'curve':'smooth','color':'$accent' if i%4 else '$secondary','line_width':.0018},width=1.1,height=.8,tracks={'trim_start':keys((0,0),(1,0),(5,.75)), 'trim_end':keys((0,0),(1.8,1),(5,1))},rotation=-14+i*.08))
        base['scenes']=[scene('thread',4,[layer('single','path',{'points':[[-.48,0],[-.24,-.17],[0,.2],[.24,-.17],[.48,0]],'curve':'smooth','color':'$accent','line_width':.012,'marker':True,'marker_size':.018},width=.82,height=.45,y=.38,enter='draw',enter_duration=2.4),type_layer('start','Follow a thought.',y=.77,size=.105,width=.85,height=.22)]),scene('weave',5,[*curves,type_layer('weave-title','LET IT\nWANDER.',y=.5,size=.21,width=.85,height=.65,scale_x=.82)],transition={'type':'cut','duration':.1}),scene('turn',5,[sculpture('loop','ribbon',x=.73,width=.55,height=.85,props={'color':'$secondary','rotation_x':-25,'rotation_z':25,'twist':3,'speed':.36}),type_layer('turn-title','A new\nperspective.',x=.3,y=.48,width=.5,height=.5,size=.11,align='left'),text('turn-sub','The same line. Another possibility.',x=.3,y=.82,width=.5,height=.14,size=.035,font='serif',align='left',enter='fade',start=.5)],transition={'type':'wipe','duration':.4}),scene('end',4,[type_layer('ending',title,y=.44,width=.82,height=.4,size=.13),layer('underline','path',{'points':[[-.32,0],[.32,0]],'color':'$accent','line_width':.004},width=.8,height=.1,y=.67,enter='draw',start=.45),text('last','Keep going.',y=.82,size=.035,font='serif',enter='fade',start=.6)],transition={'type':'crossfade','duration':.4})]
    return AnimationComposition.model_validate(base)
